// Контракт плагина ctx: типы его настроек (userConfig из plugin.json)
// и то, что он хранит в $.state.
export type CtxOptions = {
  redAt: number
  cacheMinutes: number
  showCost: boolean
}

// Последние показания, из которых собирается строка: процент контекста,
// окна лимитов (пусто, если лимитов нет: у API-ключей) и стоимость сессии в долларах.
export type CtxSnapshot = {
  percent: number | null
  rateLimits: { kind: string; percentUsed: number; resetsAt?: string }[]
  usd: number | null
}

// Учёт субагентов: последнее известное состояние каждого увиденного агента, по id агента. Слово хранится как его
// назвал движок в $.agent.list() (`running`, `completed`...), а не корзиной «работают / готово / сбой»: в корзину оно
// попадает при подсчёте строки, и слово, которого плагин не знает, там считается «работают». Исключение —
// агент, пропавший из списка, пока считался «работает»: ему записано слово `completed`. Агент, пропавший из списка,
// будучи «готово» или «сбой», хранится с прежним словом. Участников команды в нём нет. Пустой словарь — агентов нет, строки
// агентов нет. На `/clear` и `/resume` словарь не очищается: каждому известному id записывается пометка «агент прежнего
// разговора» (слово `ctx:previous-conversation`, не слово движка). Помеченный id ни в одно число строки не входит и не
// перезаписывается, даже если движок продолжает отдавать этого агента в списке; без непомеченных записей строки агентов нет.
export type AgentStates = Record<string, string>

declare module 'claude-code' {
  interface PluginState {
    // snapshot: последние показания; lastTurnAt: когда кончился последний ход
    // главной сессии, в миллисекундах по $.clock.now() (0, пока ходов не было);
    // line: последняя собранная строка (null — рисовать нечего), её читает полоса над полем ввода в приложении;
    // agents: учёт субагентов (AgentStates), из него полоса считает строку агентов.
    ctx: { snapshot: CtxSnapshot | null; lastTurnAt: number; line: string | null; agents: AgentStates }
  }
}
